"use strict";

// Turns each stories/<name>.txt into stories/built/<name>.js, so the page
// can load built-in stories with <script> tags from file://, and writes
// stories/built/manifest.js listing them. Run it after editing a story:
//
//   node scripts/build-stories.js
//
// The generated files hold each story's text unchanged, one line per line,
// and the page reads it when it loads. Stories that fail to parse are
// reported with their line numbers and nothing is written.

const fs = require("node:fs");
const path = require("node:path");
const StoryText = require("./StoryText.js");

const ROOT = path.join(__dirname, "..");
const SOURCE = path.join(ROOT, "stories");
const OUTPUT = path.join(SOURCE, "built");
const HEADER = "// Generated by scripts/build-stories.js. Edit stories/";

// { files: { relativePath: contents }, errors: [message] } for the stories
// as they are on disk. Shared with the tests, which check the output is
// up to date.
function buildOutputs() {
  const names = fs.readdirSync(SOURCE)
    .filter(function (file) { return /\.txt$/i.test(file); })
    .sort()
    .map(function (file) { return file.replace(/\.txt$/i, ""); });
  const files = {};
  const errors = [];
  for (const name of names) {
    const fileName = name + ".txt";
    const text = fs.readFileSync(path.join(SOURCE, fileName), "utf8");
    try {
      StoryText.parse(text, { fileName: fileName });
    } catch (error) {
      errors.push("stories/" + fileName + " " + error.message);
      continue;
    }
    const lines = text.replace(/^﻿/, "").replace(/\r\n?/g, "\n").replace(/\n$/, "").split("\n");
    files[name + ".js"] = HEADER + fileName + ", not this file.\n" +
      "registerStoryText(" + JSON.stringify(fileName) + ", [\n" +
      lines.map(function (line) { return "  " + JSON.stringify(line); }).join(",\n") +
      "\n]);\n";
  }
  files["manifest.js"] = HEADER + "*.txt and run it again, not this file.\n" +
    "globalThis.memoryGraphStoryFiles = " + JSON.stringify(names) + ";\n";
  return { files: files, errors: errors };
}

function build() {
  const result = buildOutputs();
  if (result.errors.length > 0) {
    console.error(result.errors.join("\n"));
    console.error("Nothing was written. Fix the error" + (result.errors.length === 1 ? "" : "s") + " above and run this again.");
    process.exitCode = 1;
    return;
  }
  fs.mkdirSync(OUTPUT, { recursive: true });
  for (const file of fs.readdirSync(OUTPUT)) {
    if (file.endsWith(".js") && !Object.prototype.hasOwnProperty.call(result.files, file)) {
      fs.unlinkSync(path.join(OUTPUT, file));
    }
  }
  for (const [file, contents] of Object.entries(result.files)) {
    fs.writeFileSync(path.join(OUTPUT, file), contents);
  }
  const count = Object.keys(result.files).length - 1;
  console.log("Built " + count + " stor" + (count === 1 ? "y" : "ies") + " into stories/built/.");
}

if (require.main === module) {
  build();
}

module.exports = { buildOutputs: buildOutputs };
